function softkom_growth_pages_definition() {
 return array(
 'ai-automation-south-africa'=>array('title'=>'AI Automation South Africa','eyebrow'=>'AI AUTOMATION · SOUTH AFRICA','headline'=>'Turn repetitive work into intelligent, scalable workflows','intro'=>'Softkom Solutions helps South African businesses use practical AI to improve sales follow-up, customer service, operations, reporting and administration — focused on measurable business value, not AI for its own sake.','problems'=>array('Leads are captured but follow-up is slow or inconsistent.','Staff repeatedly copy information between spreadsheets, email, CRM and other tools.','Customer questions consume time that could be handled automatically with human escalation.','Reporting depends on manual consolidation and information is difficult to trust.','You have AI ideas but no clear way to prioritise them.'),'solutions'=>array('AI-assisted lead capture, qualification and follow-up','Customer-service AI with human escalation','Document, email and data-processing automation','Connected workflows between existing systems','Management reporting and operational alerts','Custom AI-enabled business systems'),'faq'=>array(array('What business processes can AI automate?','Common opportunities include lead follow-up, customer enquiries, document processing, data capture, reporting, CRM updates, approvals and repetitive administration.'),array('Do we need to replace our existing software?','Not necessarily. We often connect and improve existing systems before recommending replacement.'),array('How do we know where to start with AI?','Start with repetitive, high-volume, slow or error-prone processes that affect revenue or customer experience. Our assessment helps prioritise them.'))),
 'business-process-automation-south-africa'=>array('title'=>'Business Process Automation South Africa','eyebrow'=>'BUSINESS PROCESS AUTOMATION · SOUTH AFRICA','headline'=>'Replace manual processes with connected, scalable workflows','intro'=>'When growth creates more administration instead of more capacity, the process is the problem. Softkom designs connected workflows for South African organisations that need faster hand-offs, cleaner data and better operational visibility.','problems'=>array('The same information is captured more than once.','Approvals depend on email or WhatsApp reminders.','Teams cannot easily see the current status of work.','Manual processes create errors, delays and reporting gaps.','Existing software does not match how the business operates.'),'solutions'=>array('Workflow mapping and automation','System and API integrations','Automated notifications, routing and approvals','CRM and sales-process automation','Operational dashboards and reporting','Purpose-built workflow applications'),'faq'=>array(array('What is business process automation?','It uses software, integrations and rules to perform repetitive tasks, move information between systems and guide work through consistent processes.'),array('Can you automate processes that run in spreadsheets?','Yes. Spreadsheet-driven processes are strong candidates when they involve repeated capture, approvals, status tracking or reporting.'),array('Should we automate or build a custom system?','We connect existing tools where that is efficient and design a custom system when the workflow requires more control, scale or differentiation.'))),
 'custom-business-systems-south-africa'=>array('title'=>'Custom Business Systems South Africa','eyebrow'=>'CUSTOM BUSINESS SYSTEMS · SOUTH AFRICA','headline'=>'Software built around the way your business actually works','intro'=>'Softkom designs custom business systems for organisations that have outgrown spreadsheets, disconnected SaaS tools and manual workarounds. We turn critical operations into secure, maintainable platforms that improve control, visibility and scalability.','problems'=>array('A critical process depends on spreadsheets and workarounds.','Multiple systems hold different versions of the same information.','Off-the-shelf software forces inefficient processes.','Management lacks a reliable operational view.','Growth requires adding people just to control administration.'),'solutions'=>array('Custom workflow and operations platforms','Client, supplier and partner portals','Internal management systems','CRM and pipeline solutions','Data integration and reporting platforms','AI-enabled operational systems'),'faq'=>array(array('When does a business need a custom system?','When a core process is difficult to manage with standard software, creates repeated manual work or is important enough to justify a system designed around the business.'),array('Can a custom system integrate with software we already use?','Yes. Where suitable APIs or integration methods exist, a custom system can connect existing tools instead of replacing everything.'),array('How much does a custom business system cost?','Scope, integrations and complexity determine cost. Softkom custom business-system engagements typically begin around R75,000, with larger platforms scoped separately.'))));
}

function softkom_growth_page_html($p){$a=esc_url(home_url('/assessment/'));$pro='';foreach($p['problems'] as $x){$pro.='<li><span>✓</span>'.esc_html($x).'</li>';}$sol='';foreach($p['solutions'] as $x){$sol.='<div class="skg-solution"><span>→</span><strong>'.esc_html($x).'</strong></div>';}$faq='';foreach($p['faq'] as $x){$faq.='<details><summary>'.esc_html($x[0]).'<span>+</span></summary><p>'.esc_html($x[1]).'</p></details>';}
return '<div class="softkom-growth-page"><section class="skg-hero"><div class="skg-inner"><div class="skg-pill">'.esc_html($p['eyebrow']).'</div><h1>'.esc_html($p['headline']).'</h1><p class="skg-lead">'.esc_html($p['intro']).'</p><div class="skg-actions"><a class="skg-primary" href="'.$a.'">Start My Free Assessment <b>→</b></a><a class="skg-secondary" href="'.esc_url(home_url('/contact/')).'">Book a Strategy Call</a></div><div class="skg-proof"><span>✓ 3-minute assessment</span><span>✓ Personalised maturity score</span><span>✓ Actionable recommendations</span></div></div></section><section class="skg-light"><div class="skg-inner"><div class="skg-sectionhead"><p>THE OPPORTUNITY</p><h2>Where better systems create business leverage</h2></div><div class="skg-grid"><div class="skg-problems"><h3>Common signals</h3><ul>'.$pro.'</ul></div><div class="skg-card"><p>WHAT SOFTKOM CAN DELIVER</p><h3>Practical systems. Measurable outcomes.</h3><div class="skg-solutions">'.$sol.'</div></div></div></div></section><section class="skg-band"><div class="skg-inner"><div><p>FREE BUSINESS SYSTEMS &amp; AI READINESS ASSESSMENT</p><h2>Know where to invest before you invest.</h2><span>Get a maturity score, identify the highest-value opportunities and receive a practical recommended next step.</span></div><a class="skg-blue" href="'.$a.'">Get My Readiness Score →</a></div></section><section class="skg-faq-section"><div class="skg-inner"><div class="skg-sectionhead"><p>FREQUENTLY ASKED QUESTIONS</p><h2>What businesses need to know</h2></div><div class="skg-faq">'.$faq.'</div></div></section><section class="skg-final"><div class="skg-inner"><p>READY TO IMPROVE THE WAY YOUR BUSINESS OPERATES?</p><h2>Start with clarity, not another software subscription.</h2><a class="skg-primary" href="'.$a.'">Start My Free Assessment →</a></div></section></div>';}

function softkom_growth_pages_sync(){if(get_option('softkom_growth_pages_version')==='2.0.0')return;foreach(softkom_growth_pages_definition() as $slug=>$p){$e=get_page_by_path($slug,OBJECT,'page');$x=array('post_title'=>$p['title'],'post_name'=>$slug,'post_type'=>'page','post_status'=>'publish','post_content'=>softkom_growth_page_html($p));if($e){$x['ID']=$e->ID;wp_update_post(wp_slash($x));}else{wp_insert_post(wp_slash($x));}}update_option('softkom_growth_pages_version','2.0.0',false);}add_action('init','softkom_growth_pages_sync',20);
function softkom_growth_is_page(){return is_page()&&array_key_exists(get_post_field('post_name',get_queried_object_id()),softkom_growth_pages_definition());}
function softkom_growth_body($c){if(softkom_growth_is_page())$c[]='softkom-growth-modern';return $c;}add_filter('body_class','softkom_growth_body');

