function softkom_growth_schema(){if(!softkom_growth_is_page())return;$slug=get_post_field('post_name',get_queried_object_id());$p=softkom_growth_pages_definition()[$slug];$q=array();foreach($p['faq'] as $x){$q[]=array('@type'=>'Question','name'=>$x[0],'acceptedAnswer'=>array('@type'=>'Answer','text'=>$x[1]));}$s=array('@context'=>'https://schema.org','@graph'=>array(array('@type'=>'Service','name'=>$p['title'],'provider'=>array('@type'=>'Organization','name'=>'Softkom Solutions','url'=>home_url('/')),'areaServed'=>array('@type'=>'Country','name'=>'South Africa'),'url'=>get_permalink()),array('@type'=>'FAQPage','mainEntity'=>$q)));echo '<script type="application/ld+json">'.wp_json_encode($s,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).'</script>';}add_action('wp_head','softkom_growth_schema',35);
